// SETTINGS "WHAT'S NEW" PROBE — the release train's notes reach a real learner.
// Guest visit → open Settings (gear, slot 5) → the What's-new section renders the
// bullets from tools/release-train/notes/<date>.md, dated by ship date, with no
// plumbing (header markers, "Generated by", staging sha) leaking into the panel.
//   BASE_URL=https://ssi-learning-app-git-dev-zenjin.vercel.app node e2e/settings-whats-new-probe.mjs
import { mkdirSync } from 'node:fs'
import { chromium } from '@playwright/test'

const BASE = process.env.BASE_URL || 'http://localhost:5173'
const OUT = process.env.OUT_DIR || '/tmp/whats-new/'
mkdirSync(OUT, { recursive: true })

let failures = 0
const check = (label, ok, detail = '') => { console.log(`${ok ? 'PASS' : 'FAIL'} — ${label}${detail ? ` :: ${detail}` : ''}`); if (!ok) failures++ }

const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 420, height: 860 } })
const page = await ctx.newPage()
const errors = []
page.on('pageerror', (e) => errors.push(e.message))

await page.goto(`${BASE}/?reset=1`, { waitUntil: 'networkidle' }).catch(() => {})
await page.waitForTimeout(2500)
await page.goto(BASE, { waitUntil: 'networkidle' }).catch(() => {})
await page.waitForTimeout(3500)

const gear = page.locator('.bottom-nav button[title="Settings"]')
check('settings gear present', await gear.count() === 1, page.url())
await gear.click().catch(() => {})
await page.waitForTimeout(1200)

const section = page.locator('.section.whats-new')
check('What\'s new section renders', await section.count() > 0)
await section.scrollIntoViewIfNeeded().catch(() => {})
await page.screenshot({ path: `${OUT}1-whats-new.png` })

const text = await section.innerText().catch(() => '')
const bullets = await section.locator('.whats-new-bullets li').allTextContents()
check('bullets rendered', bullets.length > 0, `${bullets.length} bullets`)
check('shows a ship date', /\d{1,2}\s\w{3}\s20\d\d/.test(text), text.split('\n')[1] || '')
check('no header markers leaked', !/release-notes:header|release-notes\.mjs/.test(text))
check('no plumbing attribution leaked', !/Generated by|promoted from|staging/i.test(text))
check('no draft leaked', !/DRAFT/i.test(text))
console.log('--- panel text ---\n' + text + '\n------------------')

// Expand, if this ship carried more than the preview count.
const more = section.locator('.whats-new-readmore')
if (await more.count()) {
  await more.first().click()
  await page.waitForTimeout(400)
  const expanded = await section.locator('.whats-new-bullets li').count()
  check('Read more expands', expanded > bullets.length, `${bullets.length} → ${expanded}`)
  await page.screenshot({ path: `${OUT}2-expanded.png` })
}

check('no page errors', errors.length === 0, errors.join(' | '))
await browser.close()
console.log(failures ? `\n${failures} FAILURES` : '\nALL PASS')
process.exit(failures ? 1 : 0)
